function hydrateIcons(root=document){$$('[data-icon]',root).forEach(el=>{if(!el.dataset.iconDone){el.innerHTML=svg(el.dataset.icon);el.dataset.iconDone='1';}})}

const state={tickets:[],team:[],settings:{},notifications:[],knowledge:[],customers:[],selected:null,view:'inbox',queue:'open',search:'',sort:'newest',filters:{priority:'all',assignee:'all',state:'all'},streaming:false,streamStatus:'',streamDraft:'',streamSources:[],composerMode:'reply',knowledgeSearch:'',knowledgeCollection:'all',customerSearch:'',draftDirty:false,settingsSection:'ai'};

async function api(path,options={}){
  const opts={...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})}};
  const res=await fetch(path,opts);if(!res.ok){let message='Request failed';try{const j=await res.json();message=j.error||message}catch{}throw new Error(message)}
  if(res.status===204)return null;return res.json();
}
function toast(title,detail='',type='success'){
  const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`<span class="toast-icon">${svg(type==='error'?'reject':'check','sm')}</span><span><strong>${escapeHtml(title)}</strong>${detail?`<small>${escapeHtml(detail)}</small>`:''}</span>`;$('#toastStack').appendChild(el);setTimeout(()=>el.remove(),3200);
}
function setBusy(el,busy,label='Working…'){if(!el)return;if(busy){el.dataset.original=el.innerHTML;el.disabled=true;el.innerHTML=`<span class="spinner"></span>${label}`}else{el.disabled=false;if(el.dataset.original)el.innerHTML=el.dataset.original;}}

async function bootstrap(){
  $('#workspace').innerHTML=$('#loadingTemplate').innerHTML;
  try{
    const data=await api('/api/bootstrap');Object.assign(state,{tickets:data.tickets,team:data.team,settings:data.settings,notifications:data.notifications});
    renderCounts();renderTickets();renderNotificationDot();hydrateIcons();
    const first=state.tickets.find(t=>t.status==='Open')||state.tickets[0];if(first)await selectTicket(first.id,false);
  }catch(e){$('#workspace').innerHTML=`<div class="workspace-empty"><div class="empty-symbol">${svg('warning')}</div><h2>Relay could not load.</h2><p>${escapeHtml(e.message)}</p><button class="button primary" data-action="reload">Try again</button></div>`;}
}
function renderCounts(){
  const open=state.tickets.filter(t=>t.status==='Open').length,pending=state.tickets.filter(t=>t.status==='Pending').length;$('#openCount').textContent=open;$('#pendingCount').textContent=pending;$('#railOpenCount').textContent=open||'';
}
function stateLabel(t){return ({new:'Needs reply',ready:'Draft ready',low:'Low confidence',edited:'Agent edited',approved:'Approved',rejected:'Rejected',generating:'Generating'})[t.state]||'Needs reply'}
function ticketPriorityClass(p){return String(p||'').toLowerCase()}
function filteredTickets(){
  let list=[...state.tickets];const q=state.search.trim().toLowerCase();
  if(state.queue!=='all')list=list.filter(t=>t.status.toLowerCase()===state.queue);
  if(q)list=list.filter(t=>[t.id,t.subject,t.summary,t.customer?.name,t.customer?.email,t.category,(t.tags||[]).join(' ')].join(' ').toLowerCase().includes(q));
  if(state.filters.priority!=='all')list=list.filter(t=>t.priority===state.filters.priority);
  if(state.filters.assignee!=='all')list=list.filter(t=>t.assignee===state.filters.assignee);
  if(state.filters.state!=='all')list=list.filter(t=>t.state===state.filters.state);
  const priorityRank={Urgent:0,High:1,Normal:2};
  if(state.sort==='oldest')list.sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));
  else if(state.sort==='priority')list.sort((a,b)=>(priorityRank[a.priority]??9)-(priorityRank[b.priority]??9));
  else if(state.sort==='confidence')list.sort((a,b)=>(a.confidence??-1)-(b.confidence??-1));
  else list.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  return list;
}
function renderTickets(){
  const list=filteredTickets();$('#ticketTotal').textContent=`${list.length} ticket${list.length===1?'':'s'}`;
  $('#ticketList').innerHTML=list.length?list.map(t=>`<button class="ticket-card ${state.selected?.id===t.id?'active':''}" data-ticket="${t.id}" data-priority="${t.priority}"><span class="ticket-avatar">${escapeHtml(t.customer?.initials||'??')}</span><span><span class="ticket-top"><span class="ticket-name">${escapeHtml(t.customer?.name||'Unknown customer')}</span><span class="ticket-time">${escapeHtml(t.updatedAt)}</span></span><span class="ticket-subject">${escapeHtml(t.subject)}</span><span class="ticket-preview">${escapeHtml(t.summary)}</span><span class="ticket-meta"><span class="state-dot ${t.state}"></span><span class="ai-state-pill">${stateLabel(t)}</span>${t.priority!=='Normal'?`<span class="priority-pill ${ticketPriorityClass(t.priority)}">${t.priority}</span>`:''}${t.status==='Pending'?'<span class="status-pill pending">Pending</span>':''}</span></span></button>`).join(''):`<div class="empty-list"><strong>No tickets found</strong><span>Try another queue or clear your filters.</span></div>`;
  hydrateIcons($('#ticketList'));renderCounts();
}
async function selectTicket(id,mobile=true){
  try{state.selected=await api(`/api/tickets/${id}`);state.draftDirty=false;renderTickets();renderWorkspace();if(mobile&&innerWidth<=900)$('#workspace').classList.add('mobile-open');}
  catch(e){toast('Could not open ticket',e.message,'error')}
}
function channelIcon(channel){return channel==='Chat'?'chat':'mail'}
function conversationMarkup(t){
  const notes=t.notes||[];
  return `<section class="conversation"><header class="conversation-header"><div class="conversation-topline"><span class="channel-icon">${svg(channelIcon(t.channel),'sm')}</span><span>${escapeHtml(t.channel)}</span><span>·</span><span>${escapeHtml(t.category)}</span><span>·</span><span>${escapeHtml(t.sentiment)}</span></div><h2>${escapeHtml(t.subject)}</h2><div class="conversation-tags">${(t.tags||[]).map(x=>`<span class="tiny-pill">${escapeHtml(x)}</span>`).join('')}</div>${state.settings.autoSummary!==false?`<div class="summary-box"><strong>Conversation summary</strong>${escapeHtml(t.summary)}</div>`:''}</header><div class="conversation-body"><div class="conversation-scroll" id="conversationScroll">${t.messages.map(m=>`<article class="message ${m.from}"><div class="message-meta"><span>${m.from==='customer'?escapeHtml(t.customer.name):'You'}</span><span>${escapeHtml(m.time)}</span></div><div class="bubble">${escapeHtml(m.text)}</div></article>`).join('')}${notes.length?`<div class="note-thread"><div class="note-thread-title">Internal notes</div>${notes.map(n=>`<div class="internal-note"><strong>${escapeHtml(n.author)} · ${escapeHtml(n.time)}</strong>${escapeHtml(n.text)}</div>`).join('')}</div>`:''}</div><div class="composer"><div class="composer-card"><div class="composer-tabs"><button class="composer-tab ${state.composerMode==='reply'?'active':''}" data-action="composer-reply">Reply</button><button class="composer-tab ${state.composerMode==='note'?'active':''}" data-action="composer-note">Internal note</button><span class="composer-helper">${state.composerMode==='reply'?'Visible to customer':'Only your team can see this'}</span></div><textarea id="composerText" placeholder="${state.composerMode==='reply'?'Write a reply…':'Add an internal note…'}"></textarea><div class="composer-actions"><button class="icon-button" style="width:30px;height:30px" data-action="insert-draft" aria-label="Use AI draft">${svg('sparkles','sm')}</button><div class="composer-spacer"></div>${state.composerMode==='reply'?`<button class="button" data-action="send-resolve">Send & resolve</button>`:''}<button class="composer-send ${state.composerMode==='note'?'note':''}" data-action="send-composer">${state.composerMode==='note'?'Add note':'Send'} ${svg('send','sm')}</button></div></div></div></div></section>`;
}
function sourceCard(s){return `<article class="source-card" data-source-card="${s.id}"><div class="source-top"><span class="source-icon">${svg('document','sm')}</span><span class="source-copy"><strong>${escapeHtml(s.title)}</strong><small>${escapeHtml(s.section)} · Updated ${escapeHtml(s.updated)}</small></span></div><p>${escapeHtml(s.excerpt)}</p><div class="source-actions"><button class="source-link" data-action="expand-source" data-id="${s.id}">Read excerpt</button><button class="source-link" data-action="open-source" data-id="${s.id}">Open article ↗</button></div></article>`}
function copilotMarkup(t){
  const draft=state.streaming?state.streamDraft:t.draft;const sources=state.streaming?state.streamSources:t.sources||[];const low=!state.streaming&&Number(t.confidence)<Number(state.settings.reviewThreshold||70)&&t.confidence!=null;
  return `<section class="copilot"><header class="copilot-header"><span class="copilot-brand">${svg('sparkles','sm')}</span><span><strong>Relay Copilot</strong><small>Grounded in workspace knowledge</small></span><span class="copilot-spacer"></span><span class="confidence ${t.confidence==null?'none':low?'low':''}">${t.confidence==null?'No score':`${t.confidence}% confidence`}</span></header><div class="copilot-scroll">${state.streaming?`<div class="generation-card"><div class="generation-status"><span class="spinner"></span><span>${escapeHtml(state.streamStatus||'Preparing assistance')}</span></div><div class="progress"><span></span></div></div>`:''}${low?`<div class="low-warning"><strong>Needs closer review.</strong> Relay found a relevant policy path, but at least one account fact is still missing. The draft avoids promising an outcome until that fact is verified.</div>`:''}${t.state==='approved'?`<div class="approved-banner"><strong>Sent with human approval.</strong> The final message is now part of the conversation and the ticket status has been updated.</div>`:''}${t.state==='rejected'?`<div class="rejected-banner"><strong>Suggestion rejected.</strong> Nothing was sent. Generate a new version or write the response manually.</div>`:''}<div class="draft-card"><div class="draft-head"><strong>${state.streaming?'Drafting response…':draft?'Suggested response':'Start with Relay'}</strong><span class="draft-badge">${state.streaming?'Working':t.state==='edited'?'Edited by agent':t.state==='approved'?'Sent':draft?'AI draft':'No draft'}</span></div><textarea class="draft-text" id="draftText" ${state.streaming||t.state==='approved'?'disabled':''} placeholder="Generate a response to pull together the conversation, customer context and relevant knowledge.">${escapeHtml(draft||'')}</textarea><div class="draft-toolbar"><select class="draft-pref" id="toneSelect" aria-label="Tone"><option ${state.settings.defaultTone==='Clear & warm'?'selected':''}>Clear & warm</option><option>Concise</option><option>Formal</option><option>Empathetic</option></select><select class="draft-pref" id="lengthSelect" aria-label="Length"><option ${state.settings.defaultLength==='Balanced'?'selected':''}>Balanced</option><option>Short</option><option>Detailed</option></select><div class="draft-spacer"></div>${!draft&&!state.streaming?`<button class="button lime" data-action="generate">${svg('sparkles','sm')} Generate response</button>`:t.state!=='approved'?`<button class="button" data-action="regenerate">${svg('refresh','sm')} Regenerate</button><button class="button" data-action="save-edit">${svg('edit','sm')} Save edit</button><button class="button primary" data-action="approve">${svg('check','sm')} Approve & send</button><button class="button danger" data-action="reject">${svg('reject','sm')}</button>`:`<button class="button" data-action="regenerate">${svg('refresh','sm')} New draft</button>`}</div></div>${state.settings.showRationale!==false&&(state.streaming||(t.rationale||[]).length)?`<div class="section-label">Why this recommendation</div><div class="reason-list">${state.streaming?`<div class="reason"><i>…</i><span>Grounding checks will appear when generation completes.</span></div>`:(t.rationale||[]).map(r=>`<div class="reason"><i>✓</i><span>${escapeHtml(r)}</span></div>`).join('')}</div>`:''}${sources.length?`<div class="section-label">Sources used · ${sources.length}</div>${sources.map(sourceCard).join('')}`:''}</div></section>`;
}
function customerMarkup(c){
  return `<aside class="customer-panel"><div class="customer-profile"><div class="customer-avatar">${escapeHtml(c.initials)}</div><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.email)}</p><div class="customer-tags">${(c.tags||[]).map(t=>`<span class="tiny-pill">${escapeHtml(t)}</span>`).join('')}</div></div><div class="context-card"><div class="context-title"><span>Customer context</span><button data-action="edit-customer" aria-label="Edit customer">${svg('edit','sm')}</button></div><div class="metric-row"><span>Plan</span><strong>${escapeHtml(c.plan)}</strong></div><div class="metric-row"><span>Customer since</span><strong>${escapeHtml(c.since)}</strong></div><div class="metric-row"><span>Lifetime value</span><strong>${money(c.lifetimeValue)}</strong></div><div class="metric-row"><span>CSAT</span><strong>${c.satisfaction?`${c.satisfaction}/5`:'—'}</strong></div><div class="metric-row"><span>Health</span><strong>${escapeHtml(c.health)}</strong></div></div><div class="context-card"><div class="context-title">Account note</div><div class="customer-note">${escapeHtml(c.notes||'No account note yet.')}</div></div><div class="context-card"><div class="context-title">Recent history</div>${(c.history||[]).map(h=>`<div class="history-item"><strong>${escapeHtml(h.label)}</strong><small>${escapeHtml(h.date)} · ${escapeHtml(h.note)}</small></div>`).join('')||'<div class="customer-note">No recent history.</div>'}</div><div class="customer-actions"><button class="button" data-action="open-customer">Full profile</button><button class="button" data-action="add-note">Add note</button></div></aside>`;
}
function renderWorkspace(){
  const t=state.selected;if(!t)return;
  $('#workspace').innerHTML=`<div class="ticket-workspace"><header class="workspace-head"><button class="icon-button mobile-back" data-action="mobile-back">${svg('arrowLeft','sm')}</button><div class="workspace-title"><strong>${escapeHtml(t.id)} · ${escapeHtml(t.customer.name)}</strong><small>${escapeHtml(t.subject)} · updated ${escapeHtml(t.updatedAt)}</small></div><div class="head-controls"><select class="head-select" data-ticket-field="status" aria-label="Status">${['Open','Pending','Resolved'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select><select class="head-select priority-select" data-ticket-field="priority" aria-label="Priority">${['Normal','High','Urgent'].map(x=>`<option ${x===t.priority?'selected':''}>${x}</option>`).join('')}</select><select class="head-select assignee-select" data-ticket-field="assignee" aria-label="Assignee">${state.team.map(a=>`<option ${a.name===t.assignee?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select><span class="head-state"><span class="state-dot ${t.state}"></span>${stateLabel(t)}</span><button class="icon-button" data-action="ticket-more" aria-label="More ticket actions">${svg('more')}</button></div></header><div class="workspace-grid">${conversationMarkup(t)}${copilotMarkup(t)}${customerMarkup(t.customer)}</div></div>`;
  hydrateIcons($('#workspace'));requestAnimationFrame(()=>{const sc=$('#conversationScroll');if(sc)sc.scrollTop=sc.scrollHeight;});
}
async function refreshTicket(ticket){state.selected=ticket;const i=state.tickets.findIndex(t=>t.id===ticket.id);if(i>=0)state.tickets[i]=ticket;else state.tickets.unshift(ticket);renderTickets();renderWorkspace();}

async function generate(){
  if(!state.selected||state.streaming)return;state.streaming=true;state.streamStatus='Starting';state.streamDraft='';state.streamSources=[];renderWorkspace();
  try{
    const res=await fetch(`/api/tickets/${state.selected.id}/generate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tone:$('#toneSelect')?.value||state.settings.defaultTone,length:$('#lengthSelect')?.value||state.settings.defaultLength})});if(!res.ok)throw new Error('Generation request failed');
    const reader=res.body.getReader(),decoder=new TextDecoder();let buffer='';
    while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines){if(!line.trim())continue;const evt=JSON.parse(line);if(evt.type==='status')state.streamStatus=evt.value;if(evt.type==='sources')state.streamSources=evt.value;if(evt.type==='chunk')state.streamDraft+=(state.streamDraft?' ':'')+evt.value;if(evt.type==='done'){state.streaming=false;state.streamStatus='';state.streamDraft='';state.streamSources=[];await refreshTicket(evt.value);toast('Draft ready','Review the confidence, reasoning and sources before sending.');}else renderWorkspace();}}
  }catch(e){state.streaming=false;renderWorkspace();toast('Could not generate response',e.message,'error')}
}
async function saveEdit(){
  const draft=$('#draftText')?.value.trim();if(!draft)return toast('Nothing to save','Write or generate a response first.','error');
  try{const t=await api(`/api/tickets/${state.selected.id}/draft`,{method:'PUT',body:JSON.stringify({draft})});await refreshTicket(t);toast('Draft saved','Relay marked this version as agent edited.')}catch(e){toast('Could not save edit',e.message,'error')}
}
function openApprove(){
  const draft=$('#draftText')?.value.trim();if(!draft)return toast('Nothing to approve','Write or generate a response first.','error');
  const low=Number(state.selected.confidence)<Number(state.settings.reviewThreshold||70);
  openModal(`<div class="modal"><header class="modal-head"><div class="modal-title"><span class="eyebrow">Human review</span><h2>Approve and send</h2></div><button class="icon-button" data-action="close-modal">${svg('reject')}</button></header><div class="modal-body">${low?`<div class="confirm-box"><strong>Low-confidence response.</strong><br>Relay is missing at least one fact needed to fully verify the outcome. Review the uncertainty and sources before sending.</div><label class="checkbox-row"><input type="checkbox" id="lowConfidenceCheck"><span>I reviewed the missing information and I’m comfortable sending this response.</span></label>`:`<div class="confirm-box" style="background:var(--teal-soft);border-color:#bee5dc"><strong>Ready for human approval.</strong><br>The final message below will be sent exactly as shown.</div>`}<div class="field" style="margin-top:14px"><label>Final response</label><textarea id="approvalDraft" style="min-height:150px">${escapeHtml(draft)}</textarea></div><label class="checkbox-row" style="margin-top:12px"><input type="checkbox" id="keepOpenCheck"><span>Keep ticket open after sending</span></label></div><footer class="modal-foot"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-approve">${svg('send','sm')} Send response</button></footer></div>`);
}
async function confirmApprove(button){
  const low=Number(state.selected.confidence)<Number(state.settings.reviewThreshold||70);if(low&&!$('#lowConfidenceCheck')?.checked)return toast('Review confirmation required','Confirm that you reviewed the low-confidence draft.','error');
  const draft=$('#approvalDraft').value.trim();if(!draft)return;setBusy(button,true,'Sending…');
  try{const t=await api(`/api/tickets/${state.selected.id}/approve`,{method:'POST',body:JSON.stringify({draft,keepOpen:$('#keepOpenCheck')?.checked})});closeModal();await refreshTicket(t);toast('Response sent',t.status==='Resolved'?'Ticket resolved successfully.':'Ticket remains open for follow-up.');renderNotificationDot();}
  catch(e){setBusy(button,false);toast('Could not send response',e.message,'error')}
}
