async function confirmReject(button){const active=$('.reject-option.active')?.dataset.rejectReason||'Rejected by agent',detail=$('#rejectDetail')?.value.trim();setBusy(button,true,'Rejecting…');try{const t=await api(`/api/tickets/${state.selected.id}/reject`,{method:'POST',body:JSON.stringify({reason:detail?`${active} — ${detail}`:active})});closeModal();await refreshTicket(t);toast('Draft rejected','Nothing was sent to the customer.')}catch(e){setBusy(button,false);toast('Could not reject draft',e.message,'error')}}

function setComposerMode(mode){state.composerMode=mode;$$('.composer-tab').forEach(b=>b.classList.toggle('active',b.dataset.action===`composer-${mode}`));const helper=$('.composer-helper'),text=$('#composerText'),send=$('.composer-send');if(helper)helper.textContent=mode==='reply'?'Visible to customer':'Only your team can see this';if(text)text.placeholder=mode==='reply'?'Write a reply…':'Add an internal note…';if(send){send.classList.toggle('note',mode==='note');send.innerHTML=`${mode==='note'?'Add note':'Send'} ${svg('send','sm')}`}}
async function sendComposer(resolve=false){
  const input=$('#composerText'),text=input?.value.trim();if(!text)return toast(state.composerMode==='note'?'Add a note first':'Write a reply first','','error');
  try{
    if(state.composerMode==='note')await refreshTicket(await api(`/api/tickets/${state.selected.id}/notes`,{method:'POST',body:JSON.stringify({text})}));
    else await refreshTicket(await api(`/api/tickets/${state.selected.id}/messages`,{method:'POST',body:JSON.stringify({text,resolve})}));
    toast(state.composerMode==='note'?'Internal note added':resolve?'Reply sent and ticket resolved':'Reply sent');
  }catch(e){toast('Could not save message',e.message,'error')}
}
