async function renderAnalytics(){
  $('#workspace').innerHTML=$('#loadingTemplate').innerHTML;try{const a=await api('/api/analytics');$('#workspace').innerHTML=`<section class="page"><div class="page-shell"><header class="page-head"><div><span class="eyebrow">Operations</span><h1>Support analytics</h1></div><p>Monitor queue health and AI review quality together. Relay treats agent decisions as the quality signal, not the number of AI messages produced.</p></header><div class="metric-grid"><div class="metric-card"><small>Open queue</small><strong>${a.headline.open}</strong><em>Active conversations</em></div><div class="metric-card"><small>Pending</small><strong>${a.headline.pending}</strong><em>Waiting on a dependency</em></div><div class="metric-card"><small>Resolved today</small><strong>${a.headline.resolvedToday}</strong><em>Across all channels</em></div><div class="metric-card"><small>AI assist rate</small><strong>${a.headline.aiAssistRate}%</strong><em>Human-reviewed replies</em></div><div class="metric-card"><small>Avg confidence</small><strong>${a.headline.avgConfidence}%</strong><em>Across generated drafts</em></div></div><div class="analytics-grid"><article class="chart-card"><h3>First-response time</h3><p>Median minutes across the last seven support periods</p><div class="line-chart">${a.responseTime.map((v,i)=>`<div class="bar ${i>3?'alt':''}" style="height:${Math.max(25,112-v*1.4)}%"><span>${v}m</span></div>`).join('')}</div></article><article class="chart-card"><h3>Confidence mix</h3><p>How often responses need closer review</p><div class="band"><span style="width:${a.confidenceBands.high}%"></span><span style="width:${a.confidenceBands.medium}%"></span><span style="width:${a.confidenceBands.low}%"></span></div><div class="legend"><div><span>High confidence</span><strong>${a.confidenceBands.high}%</strong></div><div><span>Medium</span><strong>${a.confidenceBands.medium}%</strong></div><div><span>Low</span><strong>${a.confidenceBands.low}%</strong></div></div></article><article class="chart-card"><h3>Human review outcomes</h3><p>What agents did with AI suggestions</p><div class="quality-list">${Object.entries(a.quality).map(([k,v])=>`<div class="quality-row"><div><label>${({approvedWithoutEdit:'Approved as-is',editedThenApproved:'Edited then approved',rejected:'Rejected'})[k]}</label><div class="quality-track"><span style="width:${v}%"></span></div></div><strong>${v}%</strong></div>`).join('')}</div></article><article class="chart-card"><h3>Open queue by issue</h3><p>Where support work is concentrated</p><div class="quality-list">${a.queue.map(q=>`<div class="quality-row"><div><label>${escapeHtml(q.label)}</label><div class="quality-track"><span style="width:${Math.min(100,q.value*22)}%"></span></div></div><strong>${q.value}</strong></div>`).join('')}</div></article><article class="chart-card" style="grid-column:1/-1"><h3>Recent workspace activity</h3><p>Actions across tickets, knowledge and AI review</p><div class="activity-list">${a.activity.length?a.activity.slice(0,8).map(x=>`<div class="activity-item"><span class="activity-icon">${svg(x.type==='knowledge'?'book':x.type==='ai'?'sparkles':x.type==='message'?'send':'inbox','sm')}</span><span><strong>${escapeHtml(x.text)}</strong><small>${new Date(x.time).toLocaleString()}</small></span>${x.ticketId?`<button class="button" data-open-ticket="${x.ticketId}">Open</button>`:''}</div>`).join(''):'<div class="empty-list"><strong>No activity yet</strong><span>Actions you take in Relay will appear here.</span></div>'}</div></article></div></div></section>`;hydrateIcons($('#workspace'));}catch(e){toast('Could not load analytics',e.message,'error')}
}
