function openEditCustomer(id=state.selected?.customer?.id){const c=customerFromId(id);if(!c)return;closeSheet();openModal(`<form class="modal" id="customerForm" data-id="${c.id}"><header class="modal-head"><div class="modal-title"><span class="eyebrow">Customer profile</span><h2>Edit ${escapeHtml(c.name)}</h2></div><button type="button" class="icon-button" data-action="close-modal">${svg('reject')}</button></header><div class="modal-body"><div class="form-grid"><div class="field"><label>Name</label><input name="name" value="${escapeHtml(c.name)}"></div><div class="field"><label>Email</label><input name="email" value="${escapeHtml(c.email)}"></div><div class="field"><label>Phone</label><input name="phone" value="${escapeHtml(c.phone)}"></div><div class="field"><label>Plan</label><select name="plan">${['Standard','Plus','Priority','Business'].map(x=>`<option ${x===c.plan?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Health</label><select name="health">${['Healthy','Watch','At risk','New'].map(x=>`<option ${x===c.health?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Company</label><input name="company" value="${escapeHtml(c.company)}"></div><div class="field full"><label>Tags</label><input name="tags" value="${escapeHtml((c.tags||[]).join(', '))}"></div><div class="field full"><label>Support note</label><textarea name="notes">${escapeHtml(c.notes||'')}</textarea></div></div></div><footer class="modal-foot"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">Save customer</button></footer></form>`)}
async function submitCustomer(form){const data=Object.fromEntries(new FormData(form));data.tags=data.tags.split(',').map(x=>x.trim()).filter(Boolean);const btn=form.querySelector('[type=submit]');setBusy(btn,true,'Saving…');try{const c=await api(`/api/customers/${form.dataset.id}`,{method:'PATCH',body:JSON.stringify(data)});const i=state.customers.findIndex(x=>x.id===c.id);if(i>=0)state.customers[i]=c;if(state.selected?.customer?.id===c.id){state.selected.customer=c;const ti=state.tickets.findIndex(t=>t.id===state.selected.id);if(ti>=0)state.tickets[ti].customer=c;renderWorkspace();renderTickets()}closeModal();toast('Customer updated',c.name);if(state.view==='customers')renderCustomers()}catch(e){setBusy(btn,false);toast('Could not update customer',e.message,'error')}}
function openAddNote(){openModal(`<form class="modal" id="noteForm"><header class="modal-head"><div class="modal-title"><span class="eyebrow">Internal context</span><h2>Add note to ${escapeHtml(state.selected.id)}</h2></div><button type="button" class="icon-button" data-action="close-modal">${svg('reject')}</button></header><div class="modal-body"><div class="field"><label>Note</label><textarea name="text" required placeholder="Add context for teammates or future follow-up"></textarea></div></div><footer class="modal-foot"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">Add note</button></footer></form>`)}
async function submitNote(form){const text=new FormData(form).get('text');try{const t=await api(`/api/tickets/${state.selected.id}/notes`,{method:'POST',body:JSON.stringify({text})});closeModal();await refreshTicket(t);toast('Internal note added')}catch(e){toast('Could not add note',e.message,'error')}}

function renderSettings(){
  const s=state.settings,section=state.settingsSection||'ai';
  const labels={ai:['AI assistance','Configure grounded drafting, uncertainty and human review.'],workspace:['Workspace','Set assignment and operating defaults for the support team.'],notifications:['Notifications','Choose which workspace updates appear in your notification center.'],team:['Team','See the people currently working in this support workspace.']};
  let content='';
  if(section==='ai') content=`<div class="settings-card"><h3>Human review</h3><p>Keep a clear decision boundary between generated suggestions and customer-facing messages.</p><div class="setting-row"><div><strong>Human approval required</strong><small>Relay never sends generated content without an agent action.</small></div><span class="tiny-pill" style="justify-self:end;background:var(--lime-soft);color:#568728">Always on</span></div><div class="setting-row"><div><strong>Low-confidence threshold</strong><small>Suggestions below this score require an explicit review acknowledgement.</small></div><select class="setting-control" data-setting="reviewThreshold">${[60,65,70,75,80].map(x=>`<option value="${x}" ${Number(s.reviewThreshold)===x?'selected':''}>${x}%</option>`).join('')}</select></div><div class="setting-row"><div><strong>Show recommendation rationale</strong><small>Display the grounding checks behind each draft.</small></div><button class="toggle ${s.showRationale?'on':''}" data-setting-toggle="showRationale"><span></span></button></div><div class="setting-row"><div><strong>Conversation summary</strong><small>Show the compact AI summary above the message thread.</small></div><button class="toggle ${s.autoSummary?'on':''}" data-setting-toggle="autoSummary"><span></span></button></div></div><div class="settings-card"><h3>Draft defaults</h3><p>Agents can override these controls per ticket before generation.</p><div class="setting-row"><div><strong>Default tone</strong><small>Starting voice for generated responses.</small></div><select class="setting-control" data-setting="defaultTone">${['Clear & warm','Concise','Formal','Empathetic'].map(x=>`<option ${s.defaultTone===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Default length</strong><small>Starting level of response detail.</small></div><select class="setting-control" data-setting="defaultLength">${['Short','Balanced','Detailed'].map(x=>`<option ${s.defaultLength===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Knowledge retrieval limit</strong><small>Maximum number of articles used to ground a response.</small></div><select class="setting-control" data-setting="retrievalLimit">${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(s.retrievalLimit)===x?'selected':''}>${x} sources</option>`).join('')}</select></div></div>`;
  if(section==='workspace') content=`<div class="settings-card"><h3>Routing defaults</h3><p>Defaults used when new work enters the inbox.</p><div class="setting-row"><div><strong>Default assignee</strong><small>Preselected owner when creating a ticket.</small></div><select class="setting-control" data-setting="defaultAssignee">${state.team.map(a=>`<option ${a.name===(s.defaultAssignee||'Marvellous O.')?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Business hours</strong><small>Reference hours for the support team.</small></div><input class="setting-control" data-setting="businessHours" value="${escapeHtml(s.businessHours||'09:00–18:00 WAT')}"></div></div><div class="settings-card"><h3>Agent signature</h3><p>Stored with workspace preferences for future email-channel integrations.</p><div class="field"><label>Default signature</label><textarea class="setting-control" data-setting="signature" style="height:110px;padding-top:10px">${escapeHtml(s.signature||'')}</textarea></div></div><div class="settings-card"><h3>Workspace maintenance</h3><p>Restore the original portfolio seed data after testing destructive flows.</p><div class="setting-row"><div><strong>Reset sample workspace</strong><small>Restores tickets, customers, knowledge and settings to the original state.</small></div><button class="button" data-action="reset-workspace">Reset data</button></div></div>`;
  if(section==='notifications') content=`<div class="settings-card"><h3>Notification center</h3><p>Control which categories appear in the in-app notification feed.</p><div class="setting-row"><div><strong>SLA risk alerts</strong><small>Show warnings when active tickets approach response targets.</small></div><button class="toggle ${s.showSlaNotifications!==false?'on':''}" data-setting-toggle="showSlaNotifications"><span></span></button></div><div class="setting-row"><div><strong>Knowledge updates</strong><small>Show newly published or updated knowledge guidance.</small></div><button class="toggle ${s.showKnowledgeNotifications!==false?'on':''}" data-setting-toggle="showKnowledgeNotifications"><span></span></button></div></div><div class="settings-card"><h3>Current unread items</h3><p>Your notification preferences apply immediately.</p><div class="setting-row"><div><strong>Unread notifications</strong><small>Across the categories currently enabled.</small></div><strong style="justify-self:end">${state.notifications.filter(n=>!n.read&&(n.type!=='sla'||s.showSlaNotifications!==false)&&(n.type!=='knowledge'||s.showKnowledgeNotifications!==false)).length}</strong></div></div>`;
  if(section==='team') content=`<div class="settings-card"><h3>Support team</h3><p>Current workspace members and live workload.</p><div class="activity-list">${state.team.map(a=>`<div class="activity-item"><span class="mini-avatar">${escapeHtml(a.initials)}</span><span><strong>${escapeHtml(a.name)}</strong><small>${escapeHtml(a.role)} · ${escapeHtml(a.email)}</small></span><span style="text-align:right"><strong>${a.tickets} tickets</strong><small>${escapeHtml(a.status)} · ${a.csat}/5 CSAT</small></span></div>`).join('')}</div></div>`;
  $('#workspace').innerHTML=`<section class="page"><div class="page-shell"><header class="page-head"><div><span class="eyebrow">Workspace settings</span><h1>${labels[section][0]}</h1></div><p>${labels[section][1]}</p></header><div class="settings-grid"><nav class="settings-nav"><button class="${section==='ai'?'active':''}" data-settings-section="ai">AI assistance</button><button class="${section==='workspace'?'active':''}" data-settings-section="workspace">Workspace</button><button class="${section==='notifications'?'active':''}" data-settings-section="notifications">Notifications</button><button class="${section==='team'?'active':''}" data-settings-section="team">Team</button></nav><div>${content}</div></div></div></section>`;hydrateIcons($('#workspace'));
}

async function saveSetting(key,value){try{state.settings=await api('/api/settings',{method:'PUT',body:JSON.stringify({[key]:value})});toast('Setting saved')}catch(e){toast('Could not save setting',e.message,'error')}}
async function resetWorkspace(){openModal(`<div class="modal"><header class="modal-head"><div class="modal-title"><span class="eyebrow">Reset workspace</span><h2>Restore original sample data?</h2></div><button class="icon-button" data-action="close-modal">${svg('reject')}</button></header><div class="modal-body"><div class="confirm-box">This will remove tickets, article edits and customer changes created during your current local testing session.</div></div><footer class="modal-foot"><button class="button" data-action="close-modal">Cancel</button><button class="button danger" data-action="confirm-reset">Reset workspace</button></footer></div>`)}
async function confirmReset(btn){setBusy(btn,true,'Resetting…');try{await api('/api/reset',{method:'POST'});closeModal();state.knowledge=[];state.customers=[];await bootstrap();navTo('inbox');toast('Workspace restored')}catch(e){setBusy(btn,false);toast('Could not reset workspace',e.message,'error')}}

function renderNotificationDot(){const unread=state.notifications.filter(n=>!n.read&&(n.type!=='sla'||state.settings.showSlaNotifications!==false)&&(n.type!=='knowledge'||state.settings.showKnowledgeNotifications!==false)).length;$('#notificationDot').classList.toggle('hidden',!unread)}
async function openNotifications(){try{state.notifications=await api('/api/notifications');renderNotificationDot();const visibleNotifications=state.notifications.filter(n=>(n.type!=='sla'||state.settings.showSlaNotifications!==false)&&(n.type!=='knowledge'||state.settings.showKnowledgeNotifications!==false));openSheet(`<aside class="sheet"><header class="sheet-head"><span>${svg('bell')}</span><h2>Notifications</h2><button class="button" data-action="read-all">Mark all read</button><button class="icon-button" data-action="close-sheet">${svg('reject')}</button></header><div class="sheet-body"><div class="notification-list">${visibleNotifications.length?visibleNotifications.map(n=>`<article class="notification-item ${n.read?'':'unread'}" data-notification="${n.id}" ${n.ticketId?`data-ticket-link="${n.ticketId}"`:''} ${n.knowledgeId?`data-knowledge-link="${n.knowledgeId}"`:''}><span class="notification-icon">${svg(n.type==='knowledge'?'book':n.type==='sla'?'clock':n.type==='sent'?'send':'note','sm')}</span><span><strong>${escapeHtml(n.title)}</strong><p>${escapeHtml(n.text)}</p><small>${escapeHtml(n.time)}</small></span></article>`).join(''):'<div class="empty-list"><strong>You are all caught up.</strong></div>'}</div></div></aside>`)}catch(e){toast('Could not load notifications',e.message,'error')}}
async function readNotification(id){try{await api(`/api/notifications/${id}/read`,{method:'POST'});const n=state.notifications.find(x=>x.id===id);if(n)n.read=true;renderNotificationDot()}catch{}}
async function readAll(){try{await api('/api/notifications/read-all',{method:'POST'});state.notifications.forEach(n=>n.read=true);renderNotificationDot();openNotifications()}catch(e){toast('Could not update notifications',e.message,'error')}}

async function openCommand(){
  await Promise.all([ensureKnowledge().catch(()=>{}),ensureCustomers().catch(()=>{})]);openModal(`<div class="command-modal"><div class="command-search"><span>${svg('search')}</span><input id="commandInput" placeholder="Search tickets, customers, knowledge or actions" autocomplete="off"><kbd>Esc</kbd></div><div class="command-results" id="commandResults"></div></div>`);renderCommandResults('');setTimeout(()=>$('#commandInput')?.focus(),30);
}
function renderCommandResults(q){q=q.toLowerCase().trim();const ticketMatches=state.tickets.filter(t=>!q||[t.id,t.subject,t.customer?.name].join(' ').toLowerCase().includes(q)).slice(0,5),customerMatches=state.customers.filter(c=>q&&[c.name,c.email,c.company].join(' ').toLowerCase().includes(q)).slice(0,4),kbMatches=state.knowledge.filter(k=>q&&[k.title,k.tags?.join(' ')].join(' ').toLowerCase().includes(q)).slice(0,4);const actions=[['analytics','Open analytics','chart'],['knowledge','Browse knowledge','book'],['customers','View customers','users'],['new-ticket','Create a ticket','plus'],['settings','AI settings','settings']].filter(x=>!q||x[1].toLowerCase().includes(q));$('#commandResults').innerHTML=`${ticketMatches.length?`<div class="command-group"><div class="command-label">Tickets</div>${ticketMatches.map(t=>`<button class="command-item" data-command-ticket="${t.id}"><span class="command-icon">${svg(channelIcon(t.channel),'sm')}</span><span><strong>${escapeHtml(t.id)} · ${escapeHtml(t.customer?.name)}</strong><small>${escapeHtml(t.subject)}</small></span></button>`).join('')}</div>`:''}${customerMatches.length?`<div class="command-group"><div class="command-label">Customers</div>${customerMatches.map(c=>`<button class="command-item" data-command-customer="${c.id}"><span class="command-icon">${svg('user','sm')}</span><span><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.email)}</small></span></button>`).join('')}</div>`:''}${kbMatches.length?`<div class="command-group"><div class="command-label">Knowledge</div>${kbMatches.map(k=>`<button class="command-item" data-command-knowledge="${k.id}"><span class="command-icon">${svg('book','sm')}</span><span><strong>${escapeHtml(k.title)}</strong><small>${escapeHtml(k.section)}</small></span></button>`).join('')}</div>`:''}<div class="command-group"><div class="command-label">Actions</div>${actions.map(([a,l,i])=>`<button class="command-item" data-command-action="${a}"><span class="command-icon">${svg(i,'sm')}</span><span><strong>${l}</strong></span></button>`).join('')}</div>`;hydrateIcons($('#commandResults'))}
function openProfileMenu(anchor){openPopover(anchor,`<div class="profile-summary"><span class="agent-avatar">MO</span><span><strong>Marvellous O.</strong><small>Support lead · Online</small></span></div><div class="divider"></div><button data-action="go-settings">${svg('settings','sm')} Workspace settings</button><button data-action="keyboard-shortcuts">${svg('keyboard','sm')} Keyboard shortcuts</button>`,'profile-popover')}
function openShortcuts(){openModal(`<div class="modal"><header class="modal-head"><div class="modal-title"><span class="eyebrow">Keyboard</span><h2>Move through Relay faster</h2></div><button class="icon-button" data-action="close-modal">${svg('reject')}</button></header><div class="modal-body"><div class="metric-row"><span>Command palette</span><strong><kbd>⌘</kbd> <kbd>K</kbd></strong></div><div class="metric-row"><span>Focus inbox search</span><strong><kbd>/</kbd></strong></div><div class="metric-row"><span>Next / previous ticket</span><strong><kbd>↓</kbd> <kbd>↑</kbd></strong></div><div class="metric-row"><span>Generate AI draft</span><strong><kbd>G</kbd></strong></div><div class="metric-row"><span>Edit AI draft</span><strong><kbd>E</kbd></strong></div><div class="metric-row"><span>Close layer</span><strong><kbd>Esc</kbd></strong></div></div></div>`)}

function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast('Copied to clipboard')).catch(()=>toast('Could not copy','','error'))}
function navigateRelative(delta){const list=filteredTickets();if(!list.length)return;let i=Math.max(0,list.findIndex(t=>t.id===state.selected?.id));i=(i+delta+list.length)%list.length;selectTicket(list[i].id)}

// Events
hydrateIcons();
document.addEventListener('click',async e=>{
  const nav=e.target.closest('[data-nav]');if(nav){navTo(nav.dataset.nav);return}
  const settingsSection=e.target.closest('[data-settings-section]');if(settingsSection){state.settingsSection=settingsSection.dataset.settingsSection;renderSettings();return}
  const ticket=e.target.closest('[data-ticket]');if(ticket){selectTicket(ticket.dataset.ticket);return}
  const openTicket=e.target.closest('[data-open-ticket]');if(openTicket){navTo('inbox');await selectTicket(openTicket.dataset.openTicket);return}
  const kcard=e.target.closest('[data-knowledge]');if(kcard){openArticle(kcard.dataset.knowledge);return}
  const crow=e.target.closest('[data-customer]');if(crow){openCustomer(crow.dataset.customer);return}
  const collection=e.target.closest('[data-collection]');if(collection){state.knowledgeCollection=collection.dataset.collection;renderKnowledge();return}
  const filter=e.target.closest('[data-filter-key]');if(filter){state.filters[filter.dataset.filterKey]=filter.dataset.value;closePopover();updateFilterLabel();renderTickets();return}
  const sort=e.target.closest('[data-sort-value]');if(sort){state.sort=sort.dataset.sortValue;closePopover();updateFilterLabel();renderTickets();return}
  const reason=e.target.closest('[data-reject-reason]');if(reason){$$('.reject-option').forEach(x=>x.classList.remove('active'));reason.classList.add('active');return}
  const sourceExpand=e.target.closest('[data-action="expand-source"]');if(sourceExpand){sourceExpand.closest('.source-card')?.classList.toggle('expanded');sourceExpand.textContent=sourceExpand.closest('.source-card')?.classList.contains('expanded')?'Collapse':'Read excerpt';return}
  const notification=e.target.closest('[data-notification]');if(notification){await readNotification(notification.dataset.notification);if(notification.dataset.ticketLink){closeSheet();navTo('inbox');await selectTicket(notification.dataset.ticketLink)}else if(notification.dataset.knowledgeLink){closeSheet();await ensureKnowledge();navTo('knowledge');openArticle(notification.dataset.knowledgeLink)}return}
  const commandTicket=e.target.closest('[data-command-ticket]');if(commandTicket){closeModal();navTo('inbox');await selectTicket(commandTicket.dataset.commandTicket);return}
  const commandCustomer=e.target.closest('[data-command-customer]');if(commandCustomer){closeModal();navTo('customers');await ensureCustomers();openCustomer(commandCustomer.dataset.commandCustomer);return}
  const commandKnowledge=e.target.closest('[data-command-knowledge]');if(commandKnowledge){closeModal();await ensureKnowledge();navTo('knowledge');openArticle(commandKnowledge.dataset.commandKnowledge);return}
  const commandAction=e.target.closest('[data-command-action]');if(commandAction){const a=commandAction.dataset.commandAction;closeModal();if(a==='new-ticket')openNewTicket();else navTo(a);return}
  const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
  const map={
    reload:()=>location.reload(), 'new-ticket':openNewTicket, filter:()=>openFilters(e.target.closest('[data-action]')),sort:()=>openSort(e.target.closest('[data-action]')),command:openCommand,notifications:openNotifications,'profile-menu':()=>openProfileMenu(e.target.closest('[data-action]')),
    'close-modal':closeModal,'close-sheet':closeSheet,'clear-filters':()=>{state.filters={priority:'all',assignee:'all',state:'all'};closePopover();updateFilterLabel();renderTickets()},'ticket-more':()=>openTicketMore(e.target.closest('[data-action]')),
    generate,regenerate:generate,'save-edit':saveEdit,approve:openApprove,reject:openReject,'confirm-approve':()=>confirmApprove(e.target.closest('[data-action]')),'confirm-reject':()=>confirmReject(e.target.closest('[data-action]')),
    'composer-reply':()=>setComposerMode('reply'),'composer-note':()=>setComposerMode('note'),'send-composer':()=>sendComposer(false),'send-resolve':()=>sendComposer(true),'insert-draft':()=>{if(state.selected?.draft){$('#composerText').value=state.selected.draft;setComposerMode('reply');$('#composerText').focus()}else generate()},
    'mobile-back':()=>$('#workspace').classList.remove('mobile-open'),'copy-ticket':()=>{copyText(state.selected.id);closePopover()},'mark-pending':()=>{closePopover();patchTicket('status','Pending')},'mark-resolved':()=>{closePopover();patchTicket('status','Resolved')},'add-note':()=>{closePopover();openAddNote()},
    'edit-customer':()=>openEditCustomer(e.target.closest('[data-customer-id]')?.dataset.customerId||state.selected?.customer?.id),'open-customer':()=>openCustomer(),
    'open-source':async()=>{const id=e.target.closest('[data-id]').dataset.id;await ensureKnowledge();openArticle(id)},'new-article':openNewArticle,'edit-article':()=>openEditArticle(e.target.closest('[data-id]').dataset.id),
    'read-all':readAll,'go-settings':()=>{closePopover();navTo('settings')},'keyboard-shortcuts':()=>{closePopover();openShortcuts()},
    'reset-workspace':resetWorkspace,'confirm-reset':()=>confirmReset(e.target.closest('[data-action]'))
  };map[action]?.();
});

document.addEventListener('change',e=>{
  const field=e.target.dataset.ticketField;if(field&&state.selected)patchTicket(field,e.target.value);
  const setting=e.target.dataset.setting;if(setting){let value=e.target.value;if(['reviewThreshold','retrievalLimit'].includes(setting))value=Number(value);saveSetting(setting,value)}
});
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-setting-toggle]');if(toggle){const key=toggle.dataset.settingToggle,value=!state.settings[key];state.settings[key]=value;toggle.classList.toggle('on',value);saveSetting(key,value).then(()=>{renderNotificationDot();if(state.view==='settings'&&state.settingsSection==='notifications')renderSettings()})}});
document.addEventListener('input',e=>{
  if(e.target.id==='ticketSearch'){state.search=e.target.value;renderTickets()}
  if(e.target.id==='knowledgeSearch'){state.knowledgeSearch=e.target.value;renderKnowledge()}
  if(e.target.id==='customerSearch'){state.customerSearch=e.target.value;renderCustomers()}
  if(e.target.id==='commandInput')renderCommandResults(e.target.value);
  if(e.target.id==='draftText')state.draftDirty=e.target.value!==state.selected?.draft;
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='newTicketForm')submitNewTicket(e.target);if(e.target.id==='articleForm')submitArticle(e.target);if(e.target.id==='editArticleForm')submitEditArticle(e.target);if(e.target.id==='customerForm')submitCustomer(e.target);if(e.target.id==='noteForm')submitNote(e.target)});
$$('.queue-tab').forEach(btn=>btn.addEventListener('click',()=>{$$('.queue-tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');state.queue=btn.dataset.queue;renderTickets()}));
$('#modalLayer').addEventListener('click',e=>{if(e.target.id==='modalLayer')closeModal()});$('#sheetLayer').addEventListener('click',e=>{if(e.target.id==='sheetLayer')closeSheet()});
document.addEventListener('click',e=>{if(!e.target.closest('.popover')&&!e.target.closest('[data-action="profile-menu"]')&&!e.target.closest('[data-action="filter"]')&&!e.target.closest('[data-action="sort"]')&&!e.target.closest('[data-action="ticket-more"]'))closePopover()});
document.addEventListener('keydown',e=>{
  const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand();return}
  if(e.key==='Escape'){closePopover();if($('#modalLayer').classList.contains('open'))closeModal();else if($('#sheetLayer').classList.contains('open'))closeSheet();else if(innerWidth<=900)$('#workspace').classList.remove('mobile-open');return}
  if(e.key==='/'&&!typing&&state.view==='inbox'){e.preventDefault();$('#ticketSearch')?.focus();return}
  if(!typing&&state.view==='inbox'){if(e.key==='ArrowDown'){e.preventDefault();navigateRelative(1)}if(e.key==='ArrowUp'){e.preventDefault();navigateRelative(-1)}if(e.key.toLowerCase()==='g'&&state.selected){e.preventDefault();generate()}if(e.key.toLowerCase()==='e'&&state.selected?.draft){e.preventDefault();$('#draftText')?.focus()}}
});
window.addEventListener('resize',()=>closePopover());

updateFilterLabel();bootstrap();
